import subprocess
def status(args):
    r=subprocess.run(["./executable"]+args, capture_output=True, text=True, timeout=15)
    return r.returncode, r.stdout.strip(), r.stderr.strip()
def member(ch, charset):
    rc,out,err=status(["-i","assets/password-test.zip","-c",charset,"--minPasswordLen","1","--maxPasswordLen","1","-w","1","-s",ch])
    if "out of the generation charset" in err:
        return False
    return (rc,out,err)
# test weird chars in s
for ch in ["\t","\n","é","€","~"," "]:
    print("s",repr(ch), member(ch,"s"))
for cs in ["l","u","d","h","H","lud","s","lh","Hh"]:
    for ch in ["a","f","g","A","F","G","0","9"," "]:
        print(cs,ch,member(ch,cs) if member(ch,cs)==False else "in")
    print("---")
PY
"}

