{"command":"cat > src/errors.rs << 'EOF'
use std::fmt;

#[derive(Debug)]
pub enum AppError {
    Cli(String),
    Io(std::io::Error),
    InvalidZip(String),
    FileNumberNotFound(usize),
}

impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            AppError::Cli(message) => write!(f, "CLI argument error - {:?}", message),
            AppError::Io(error) => write!(f, "standard I/O error - {}", error),
            AppError::InvalidZip(message) => write!(f, "Invalid zip file error - {}", message),
            AppError::FileNumberNotFound(file_number) => {
                write!(f, "File number not found within archive error - '{}'", file_number)
            }
        }
    }
}

impl std::error::Error for AppError {}

impl From<std::io::Error> for AppError {
    fn from(error: std::io::Error) -> Self {
        AppError::Io(error)
    }
}

pub type AppResult<T> = Result<T, AppError>;
EOF
cat > src/crypto.rs << 'EOF'
// Cryptographic primitives implemented from their public specifications:
// CRC-32 (as used by the ZIP format), SHA-1, HMAC-SHA1/PBKDF2 and the
// forward AES block cipher used in WinZip AES counter mode, plus the
// traditional PKZIP stream cipher.

pub const fn make_crc_table() -> [u32; 256] {
    let mut table = [0u32; 256];
    let mut i = 0usize;
    while i < 256 {
        let mut c = i as u32;
        let mut k = 0;
        while k < 8 {
            c = if c & 1 != 0 { 0xedb88320 ^ (c >> 1) } else { c >> 1 };
            k += 1;
        }
        table[i] = c;
        i += 1;
    }
    table
}

pub static CRC_TABLE: [u32; 256] = make_crc_table();

#[inline]
pub fn crc32_update_raw(crc: u32, byte: u8) -> u32 {
    CRC_TABLE[((crc ^ byte as u32) & 0xff) as usize] ^ (crc >> 8)
}

pub fn crc32(data: &[u8]) -> u32 {
    let mut crc = 0xffffffffu32;
    for &b in data {
        crc = crc32_update_raw(crc, b);
    }
    crc ^ 0xffffffff
}

// ---------- SHA-1 ----------

#[derive(Clone)]
pub struct Sha1 {
    state: [u32; 5],
    buffer: [u8; 64],
    buffer_len: usize,
    total_len: u64,
}

impl Sha1 {
    pub fn new() -> Self {
