#[derive(Clone)]
struct HmacSha1 {
    inner_state: [u32; 5],
    outer_state: [u32; 5],
}

impl HmacSha1 {
    fn new(key: &[u8]) -> Self {
        let mut key_block = [0u8; 64];
        if key.len() > 64 {
            let digest = sha1(key);
            key_block[..20].copy_from_slice(&digest);
        } else {
            key_block[..key.len()].copy_from_slice(key);
        }
        let mut inner_pad = [0u8; 64];
        let mut outer_pad = [0u8; 64];
        for i in 0..64 {
            inner_pad[i] = key_block[i] ^ 0x36;
            outer_pad[i] = key_block[i] ^ 0x5c;
        }
        let mut inner = Sha1::new();
        inner.update(&inner_pad);
        let mut outer = Sha1::new();
        outer.update(&outer_pad);
        HmacSha1 { inner_state: inner.state, outer_state: outer.state }
    }

    fn compute(&self, message: &[u8]) -> [u8; 20] {
        let mut inner = Sha1::from_state(self.inner_state, 64);
        inner.update(message);
        let inner_digest = inner.finalize();
        let mut outer = Sha1::from_state(self.outer_state, 64);
        outer.update(&inner_digest);
        outer.finalize()
    }
}

pub fn pbkdf2_hmac_sha1(password: &[u8], salt: &[u8], iterations: u32, output: &mut [u8]) {
    let hmac = HmacSha1::new(password);
    let mut block_index = 1u32;
    let mut offset = 0usize;
    while offset < output.len() {
        let mut first_message = Vec::with_capacity(salt.len() + 4);
        first_message.extend_from_slice(salt);
        first_message.extend_from_slice(&block_index.to_be_bytes());
        let mut u = hmac.compute(&first_message);
        let mut t = u;
        let mut i = 1;
        while i < iterations {
            u = hmac.compute(&u);
            for j in 0..20 {
                t[j] ^= u[j];
            }
            i += 1;
        }
        let take = std::cmp::min(20, output.len() - offset);
        output[offset..offset + take].copy_from_slice(&t[..take]);
        offset += take;
        block_index += 1;
    }
}

pub fn hmac_sha1(key: &[u8], message: &[u8]) -> [u8; 20] {
