#[inline]
fn mul(a: u8, mut b: u8) -> u8 {
    let mut result = 0u8;
    let mut aa = a;
    while b != 0 {
        if b & 1 != 0 {
            result ^= aa;
        }
        aa = xtime(aa);
        b >>= 1;
