            if i % nk == 0 {
                temp = [
                    SBOX[temp[1] as usize] ^ RCON[i / nk - 1],
                    SBOX[temp[2] as usize],
                    SBOX[temp[3] as usize],
                    SBOX[temp[0] as usize],
                ];
            } else if nk > 6 && i % nk == 4 {
                temp = [
                    SBOX[temp[0] as usize],
                    SBOX[temp[1] as usize],
                    SBOX[temp[2] as usize],
                    SBOX[temp[3] as usize],
                ];
            }
            let prev = words[i - nk];
            words.push([
                prev[0] ^ temp[0],
                prev[1] ^ temp[1],
                prev[2] ^ temp[2],
                prev[3] ^ temp[3],
            ]);
        }
        let mut round_keys = Vec::with_capacity(rounds + 1);
        for r in 0..=rounds {
            let mut key_block = [0u8; 16];
            for c in 0..4 {
                key_block[c * 4..c * 4 + 4].copy_from_slice(&words[r * 4 + c]);
            }
            round_keys.push(key_block);
        }
        Some(AesCipher { round_keys, rounds })
    }

    pub fn encrypt_block(&self, input: &[u8; 16]) -> [u8; 16] {
        let mut state = *input;
        add_round_key(&mut state, &self.round_keys[0]);
        for round in 1..self.rounds {
            sub_bytes(&mut state);
            shift_rows(&mut state);
            mix_columns(&mut state);
            add_round_key(&mut state, &self.round_keys[round]);
        }
        sub_bytes(&mut state);
        shift_rows(&mut state);
        add_round_key(&mut state, &self.round_keys[self.rounds]);
        state
    }
}

fn add_round_key(state: &mut [u8; 16], key: &[u8; 16]) {
    for i in 0..16 {
        state[i] ^= key[i];
    }
}

fn sub_bytes(state: &mut [u8; 16]) {
    for b in state.iter_mut() {
        *b = SBOX[*b as usize];
    }
}

fn shift_rows(state: &mut [u8; 16]) {
    let old = *state;
    // State is column-major: state[row + 4*col].
    for row in 0..4 {
        for col in 0..4 {
            state[row + 4 * col] = old[row + 4 * ((col + row) % 4)];
        }
    }
}

fn mix_columns(state: &mut [u8; 16]) {
    for col in 0..4 {
        let i = col * 4;
        let (a0, a1, a2, a3) = (state[i], state[i + 1], state[i + 2], state[i + 3]);
        state[i] = mul(a0, 2) ^ mul(a1, 3) ^ a2 ^ a3;
        state[i + 1] = a0 ^ mul(a1, 2) ^ mul(a2, 3) ^ a3;
        state[i + 2] = a0 ^ a1 ^ mul(a2, 2) ^ mul(a3, 3);
        state[i + 3] = mul(a0, 3) ^ a1 ^ a2 ^ mul(a3, 2);
    }
}

// ---------- Traditional ZIP cipher ----------

pub struct ZipCrypto {
    key0: u32,
    key1: u32,
    key2: u32,
}

impl ZipCrypto {
    pub fn new(password: &[u8]) -> Self {
        let mut cipher = ZipCrypto { key0: 0x12345678, key1: 0x23456789, key2: 0x34567890 };
        for &b in password {
            cipher.update_keys(b);
        }
        cipher
    }

    fn update_keys(&mut self, byte: u8) {
        self.key0 = crc32_update_raw(self.key0, byte);
        self.key1 = (self.key1.wrapping_add(self.key0 & 0xff)).wrapping_mul(134775813).wrapping_add(1);
        self.key2 = crc32_update_raw(self.key2, (self.key1 >> 24) as u8);
    }

    #[inline]
    fn decrypt_byte(&self) -> u8 {
        let temp = (self.key2 & 0xffff) | 2;
        ((temp.wrapping_mul(temp ^ 1)) >> 8) as u8
    }

    pub fn decrypt(&mut self, data: &[u8]) -> Vec<u8> {
        let mut out = Vec::with_capacity(data.len());
        for &c in data {
            let plain = c ^ self.decrypt_byte();
            self.update_keys(plain);
            out.push(plain);
        }
        out
    }
}
