#[derive(Debug)]
pub struct DecompressError;

type Result<T> = std::result::Result<T, DecompressError>;

// Supported method identifiers as used by the original program.  Methods
// outside this list are reported by the caller as unsupported.
pub fn is_supported_method(method: u16) -> bool {
    matches!(method, 0 | 8 | 9 | 12 | 14 | 93 | 95 | 98)
}

pub fn decompress(method: u16, data: &[u8], expected_size: u64) -> Result<Vec<u8>> {
    match method {
        0 => Ok(data.to_vec()),
        8 | 9 => inflate(data),
