pub fn inflate(data: &[u8]) -> Result<Vec<u8>> {
    let mut reader = BitReader::new(data);
    let mut out: Vec<u8> = Vec::new();
    loop {
        let final_block = reader.bits(1)? == 1;
        let block_type = reader.bits(2)?;
        match block_type {
            0 => {
                reader.align_byte();
                // After alignment the next bits come from complete bytes
                // which are still partly held in the bit buffer.
                let mut stored: Vec<u8> = Vec::new();
                while reader.bit_count >= 8 {
                    stored.push((reader.bit_buffer & 0xff) as u8);
                    reader.bit_buffer >>= 8;
                    reader.bit_count -= 8;
                }
                // Read LEN and NLEN from the stored byte stream.
                let remaining = &reader.data[reader.pos..];
                let mut stream = stored;
                stream.extend_from_slice(remaining);
