                // Rebuild the reader on the unconsumed input.
                let consumed_from_original = stream.len() - remaining.len() + 4 + len;
                reader = BitReader::new(&reader.data[reader.pos - (stream.len() - remaining.len()) + consumed_from_original - (4 + len) + (4 + len)..]);
                // The expression above reduces to the bytes following the
                // stored block; reset explicitly for clarity:
                let bytes_already_buffered = stored.len();
                let original_consumed = reader.pos;
