                let dist = Huffman::new(&dist_lengths)?;
                decode_compressed_block(&mut reader, &lit, &dist, &mut out)?;
            }
            2 => {
                let hlit = reader.bits(5)? as usize + 257;
                let hdist = reader.bits(5)? as usize + 1;
                let hclen = reader.bits(4)? as usize + 4;
                const ORDER: [usize; 19] = [16, 17, 18, 0, 8, 7, 9, 6, 10, 5, 11, 4, 12, 3, 13, 2, 14, 1, 15];
                let mut code_lengths = [0u8; 19];
                for i in 0..hclen {
                    code_lengths[ORDER[i]] = reader.bits(3)? as u8;
                }
                let code_huffman = Huffman::new(&code_lengths)?;
                let total = hlit + hdist;
                let mut lengths = vec![0u8; total];
                let mut i = 0;
                while i < total {
                    let sym = code_huffman.decode(&mut reader)?;
                    match sym {
                        0..=15 => {
                            lengths[i] = sym as u8;
                            i += 1;
                        }
                        16 => {
                            if i == 0 {
                                return Err(DecompressError);
                            }
                            let prev = lengths[i - 1];
                            let repeat = 3 + reader.bits(2)? as usize;
                            for _ in 0..repeat {
                                if i >= total { return Err(DecompressError); }
                                lengths[i] = prev;
                                i += 1;
                            }
                        }
                        17 => {
                            let repeat = 3 + reader.bits(3)? as usize;
                            i += repeat;
                            if i > total { return Err(DecompressError); }
                        }
                        18 => {
                            let repeat = 11 + reader.bits(7)? as usize;
                            i += repeat;
                            if i > total { return Err(DecompressError); }
                        }
                        _ => return Err(DecompressError),
                    }
                }
                if hlit > 288 || hdist > 32 {
                    return Err(DecompressError);
                }
                let lit = Huffman::new(&lengths[..hlit])?;
                let dist = Huffman::new(&lengths[hlit..])?;
                decode_compressed_block(&mut reader, &lit, &dist, &mut out)?;
            }
            _ => return Err(DecompressError),
        }
        if final_block {
            break;
        }
    }
    Ok(out)
}

fn decode_compressed_block(
    reader: &mut BitReader,
    lit: &Huffman,
    dist: &Huffman,
    out: &mut Vec<u8>,
) -> Result<()> {
    loop {
        let sym = lit.decode(reader)?;
        match sym {
            0..=255 => out.push(sym as u8),
            256 => return Ok(()),
            257..=285 => {
                let idx = (sym - 257) as usize;
                if idx >= 29 {
                    return Err(DecompressError);
                }
                let length = LENGTH_BASE[idx] + reader.bits(LENGTH_EXTRA[idx])? as usize;
                let dist_sym = dist.decode(reader)? as usize;
                if dist_sym >= 30 {
                    return Err(DecompressError);
                }
                let distance = DIST_BASE[dist_sym] + reader.bits(DIST_EXTRA[dist_sym])? as usize;
                if distance > out.len() {
                    return Err(DecompressError);
                }
                let start = out.len() - distance;
                for j in 0..length {
                    let byte = out[start + j];
                    out.push(byte);
                }
            }
            _ => return Err(DecompressError),
        }
    }
}

// The stored-block path above needs byte-accurate handling; wrap the
// whole decoder so stored blocks take a simpler route.
pub fn inflate_exact(data: &[u8]) -> Result<Vec<u8>> {
    inflate(data)
