// Password candidate generation for brute-force searches.
//
// Passwords are generated in increasing length.  Within one length the
// order is lexicographic with respect to the (sorted) generation
// charset, with the rightmost position changing fastest:
//
//     aa, ab, ac, ba, bb, bc, ...
//
// When an explicit starting password is supplied, generation starts at
// that password within its own length and then continues with the whole
// of every following length.  For compatibility with the observed
// program, the very last password of the whole search space is not
// produced from such a continued sequence (it is only produced when it
// is the starting password itself, or when no starting password was
// supplied at all).

use std::collections::BTreeSet;

#[derive(Clone)]
pub struct PasswordGenerator {
    charset: Vec<char>,
    max_len: usize,
    state: GeneratorState,
    explicit_start: bool,
}

#[derive(Clone)]
enum GeneratorState {
    NotStarted { initial_len: usize, starting: Option<Vec<char>> },
    Running { indices: Vec<usize> },
    Finished,
}

impl PasswordGenerator {
    pub fn new(
        charset: &BTreeSet<char>,
        min_len: usize,
        max_len: usize,
        starting_password: Option<&str>,
    ) -> Self {
        let (initial_len, starting) = match starting_password {
            Some(password) => {
                let chars: Vec<char> = password.chars().collect();
                (chars.len(), Some(chars))
            }
            None => (min_len, None),
        };
        PasswordGenerator {
            charset: charset.iter().copied().collect(),
            max_len,
            state: GeneratorState::NotStarted { initial_len, starting },
            explicit_start: starting_password.is_some(),
        }
    }

    fn first_char(&self) -> char {
        // This call is the one workers make when a generated search is
        // started; an empty charset is a programming/configuration error
        // there and is reported in the same way as the original program.
        *self.charset.first().expect("charset non empty")
    }

    fn char_at(&self, index: usize) -> char {
        self.charset[index]
    }

    fn is_final(&self, indices: &[usize]) -> bool {
        !self.charset.is_empty()
            && indices.len() == self.max_len
            && indices.iter().all(|&i| i + 1 == self.charset.len())
    }

    fn indices_to_string(&self, indices: &[usize]) -> String {
        indices.iter().map(|&i| self.char_at(i)).collect()
    }
}

impl Iterator for PasswordGenerator {
    type Item = String;

    fn next(&mut self) -> Option<Self::Item> {
        match self.state.clone() {
            GeneratorState::Finished => None,
            GeneratorState::NotStarted { initial_len, starting } => {
                let indices: Vec<usize> = match &starting {
                    Some(chars) => chars
                        .iter()
                        .map(|c| self.charset.iter().position(|x| x == c).unwrap_or(0))
                        .collect(),
                    None => {
                        let first = self.first_char();
                        let _ = first;
                        vec![0usize; initial_len]
                    }
                };
                let result = self.indices_to_string(&indices);
                self.state = GeneratorState::Running { indices };
                Some(result)
            }
            GeneratorState::Running { mut indices } => {
                // Advance the odometer, carrying from the right.
                let mut position = indices.len();
                let advanced = loop {
                    if position == 0 {
                        break false;
                    }
                    position -= 1;
                    if indices[position] + 1 < self.charset.len() {
                        indices[position] += 1;
                        for later in position + 1..indices.len() {
                            indices[later] = 0;
                        }
                        break true;
                    }
                    indices[position] = 0;
                };
                if !advanced {
                    if indices.len() >= self.max_len {
                        self.state = GeneratorState::Finished;
                        return None;
                    }
                    indices = vec![0usize; indices.len() + 1];
                }
                if self.explicit_start && self.is_final(&indices) {
                    self.state = GeneratorState::Finished;
                    return None;
                }
                let result = self.indices_to_string(&indices);
                self.state = GeneratorState::Running { indices };
                Some(result)
            }
        }
    }
}
