// directory.  Error messages for the most common forms of corruption
// intentionally match the messages produced for invalid archives.
fn parse_central_directory(bytes: &[u8]) -> AppResult<Vec<ZipEntry>> {
    let eocd_positions = find_eocd_candidates(bytes);
    if eocd_positions.is_empty() {
