fn find_eocd_candidates(bytes: &[u8]) -> Vec<usize> {
    let mut positions = Vec::new();
    if bytes.len() < 4 {
        return positions;
    }
    let mut i = bytes.len() - 4;
    loop {
        if bytes[i..i + 4] == [0x50, 0x4b, 0x05, 0x06] {
            positions.push(i);
        }
        if i == 0 {
