struct EocdInfo {
    total_entries: u64,
    central_size: u64,
    central_offset: u64,
}

fn read_eocd(bytes: &[u8], eocd_pos: usize) -> AppResult<EocdInfo> {
    if eocd_pos + 22 > bytes.len() {
        return Err(invalid_zip("invalid Zip archive: Could not find EOCD"));
    }
    let mut total = u16_at(bytes, eocd_pos + 10) as u64;
    let mut size = u32_at(bytes, eocd_pos + 12) as u64;
    let mut offset = u32_at(bytes, eocd_pos + 16) as u64;

    // ZIP64 end of central directory, when any ordinary field is set to
    // its sentinel value.
    if total == 0xffff || size == 0xffffffff || offset == 0xffffffff {
        if eocd_pos >= 20 {
            let locator = eocd_pos - 20;
            if bytes[locator..locator + 4] == [0x50, 0x4b, 0x06, 0x07] {
                let zip64_pos = u64_at(bytes, locator + 8) as usize;
                if zip64_pos + 56 <= bytes.len()
                    && bytes[zip64_pos..zip64_pos + 4] == [0x50, 0x4b, 0x06, 0x06]
                {
