fn find_extra_field<'a>(extra: &'a [u8], wanted_tag: u16) -> Option<&'a [u8]> {
    let mut cursor = 0usize;
    while cursor + 4 <= extra.len() {
        let tag = u16_at(extra, cursor);
        let size = u16_at(extra, cursor + 2) as usize;
        cursor += 4;
        if cursor + size > extra.len() {
            return None;
        }
        if tag == wanted_tag {
            return Some(&extra[cursor..cursor + size]);
        }
        cursor += size;
    }
    None
}

fn parse_aes_extra(extra: &[u8], method: u16) -> AppResult<Option<AesInfo>> {
    let mut cursor = 0usize;
    let mut aes: Option<AesInfo> = None;
    let mut saw_extra_field = false;
    while cursor < extra.len() {
        if cursor + 4 > extra.len() {
            return Err(invalid_zip("invalid Zip archive: Extra field header truncated"));
        }
        saw_extra_field = true;
        let tag = u16_at(extra, cursor);
        let size = u16_at(extra, cursor + 2) as usize;
        cursor += 4;
        if cursor + size > extra.len() {
            // Some tags are parsed eagerly by archive readers and report
            // their own truncation error.
            if tag == 0x0001 {
                return Err(invalid_zip("invalid Zip archive: ZIP64 extra field truncated"));
            }
            return Err(invalid_zip(
                "invalid Zip archive: Variable-length field extends beyond file boundary",
            ));
        }
        let data = &extra[cursor..cursor + size];
        if tag == 0x9901 {
            if size != 7 {
                return Err(invalid_zip(
                    "unsupported Zip archive: AES extra data field has an unsupported length",
                ));
            }
            if aes.is_none() {
                if &data[2..4] != b"AE" {
                    return Err(invalid_zip("invalid Zip archive: Invalid AES vendor"));
                }
                let version = u16::from_le_bytes([data[0], data[1]]);
                if version != 1 && version != 2 {
                    return Err(invalid_zip("invalid Zip archive: Invalid AES vendor version"));
                }
                let strength = data[4];
                if !(1..=3).contains(&strength) {
                    return Err(invalid_zip("invalid Zip archive: Invalid AES encryption strength"));
                }
                let actual_method = u16::from_le_bytes([data[5], data[6]]);
                aes = Some(AesInfo { version, strength, actual_method });
            }
        }
        if tag == 0x000a && size != 32 && size != 24 {
            // NTFS attributes have a fixed recorded layout in readers
            // that understand the tag.
            // (Only very short values have been observed to be rejected
            // here; be conservative and ignore other sizes.)
            if size < 8 {
                return Err(invalid_zip(
                    "unsupported Zip archive: NTFS extra field has an unsupported length",
                ));
            }
        }
        cursor += size;
    }
    let _ = saw_extra_field;
    if method == METHOD_AES && aes.is_none() {
        return Err(invalid_zip(
            "invalid Zip archive: AES encryption without AES extra data field",
        ));
    }
    Ok(aes)
}

