{"command":"cat >> src/zip_utils.rs << 'EOF'

// ---------- Password checking data ----------

#[derive(Debug)]
pub enum UnexpectedError {
    UnsupportedArchive(&'static str),
    Io(std::io::Error),
}

pub enum CheckResult {
    Correct,
    Incorrect,
    Unexpected(UnexpectedError),
}

#[derive(Debug)]
enum ZipReadError {
    Io(std::io::Error),
}

pub struct PasswordChecker {
    method: u16,
    crc32: u32,
    uncompressed_size: u64,
    kind: CheckerKind,
}

enum CheckerKind {
    Traditional {
        check_byte: u8,
        encrypted: Vec<u8>,
    },
    Aes {
        info: AesInfo,
        salt: Vec<u8>,
        verifier: Vec<u8>,
        after_verifier: Vec<u8>,
    },
}

impl SelectedEntry {
    pub fn into_checker(self) -> PasswordChecker {
        let start = self.data_offset;
        let available = if start < self.archive_bytes.len() {
            let wanted = self.entry.compressed_size;
            let end = if wanted > (self.archive_bytes.len() - start) as u64 {
                self.archive_bytes.len()
            } else {
                start + wanted as usize
            };
            &self.archive_bytes[start..end]
        } else {
            &[]
        };
        let raw = available.to_vec();
        match &self.entry.aes_info {
            None => {
                let check_byte = if self.entry.flags & 0x0008 != 0 {
                    (self.entry.mod_time >> 8) as u8
                } else {
                    (self.entry.crc32 >> 24) as u8
                };
                PasswordChecker {
                    method: self.entry.method,
                    crc32: self.entry.crc32,
                    uncompressed_size: self.entry.uncompressed_size,
                    kind: CheckerKind::Traditional { check_byte, encrypted: raw },
                }
            }
            Some(info) => {
                let salt_len = info.salt_len();
                // Constructing the reader for an AES entry reads its
                // salt and password-verification value up front.  The
                // archive has been validated by this point, so a short
                // entry is not expected here.
                let header_len = salt_len + 2;
                if raw.len() < header_len {
                    let mut buffer = vec![0u8; header_len];
                    use std::io::Read;
                    let result: Result<(), ZipReadError> = (&raw[..])
                        .read_exact(&mut buffer)
                        .map_err(ZipReadError::Io);
                    let _validated: () = result.expect("Archive validated before-hand");
                    unreachable!()
                }
                PasswordChecker {
                    method: info.actual_method,
                    crc32: self.entry.crc32,
                    uncompressed_size: self.entry.uncompressed_size,
                    kind: CheckerKind::Aes {
                        info: info.clone(),
                        salt: raw[..salt_len].to_vec(),
                        verifier: raw[salt_len..salt_len + 2].to_vec(),
                        after_verifier: raw[salt_len + 2..].to_vec(),
                    },
                }
            }
        }
    }
}

impl PasswordChecker {
    pub fn is_supported_method(&self) -> bool {
        crate::decompress::is_supported_method(self.method)
    }

    pub fn check(&self, password: &str) -> CheckResult {
        match &self.kind {
            CheckerKind::Traditional { check_byte, encrypted } => {
                if !self.is_supported_method() {
                    return CheckResult::Unexpected(UnexpectedError::UnsupportedArchive(
                        "Compression method not supported",
                    ));
                }
                if encrypted.len() < 12 {
                    use std::io::Read;
                    let mut buffer = [0u8; 12];
                    let error = (&encrypted[..])
                        .read_exact(&mut buffer)
                        .err()
                        .unwrap_or_else(|| {
                            std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "failed to fill whole buffer")
                        });
                    return CheckResult::Unexpected(UnexpectedError::Io(error));
                }
                let mut cipher = crypto::ZipCrypto::new(password.as_bytes());
                let header = cipher.decrypt(&encrypted[..12]);
                if header[11] != *check_byte {
                    return CheckResult::Incorrect;
                }
                let compressed = cipher.decrypt(&encrypted[12..]);
                let plain = match crate::decompress::decompress(self.method, &compressed, self.uncompressed_size) {
                    Ok(plain) => plain,
                    Err(_) => return CheckResult::Incorrect,
                };
                if plain.len() as u64 != self.uncompressed_size {
                    return CheckResult::Incorrect;
                }
                if crypto::crc32(&plain) != self.crc32 {
                    return CheckResult::Incorrect;
                }
                CheckResult::Correct
            }
            CheckerKind::Aes { info, salt, verifier, after_verifier } => {
                let key_len = info.key_len();
                let mut derived = vec![0u8; 2 * key_len + 2];
                crypto::pbkdf2_hmac_sha1(password.as_bytes(), salt, 1000, &mut derived);
                if &derived[2 * key_len..] != verifier.as_slice() {
                    return CheckResult::Incorrect;
                }
                if !self.is_supported_method() {
                    return CheckResult::Unexpected(UnexpectedError::UnsupportedArchive(
                        "Compression method not supported",
                    ));
                }
                if after_verifier.len() < 10 {
                    if after_verifier.is_empty() && self.uncompressed_size == 0 {
                        return CheckResult::Correct;
                    }
                    return CheckResult::Incorrect;
                }
                let cipher_len = after_verifier.len() - 10;
                let ciphertext = &after_verifier[..cipher_len];
                let auth = &after_verifier[cipher_len..];
                if ciphertext.is_empty() {
                    if self.uncompressed_size == 0 {
                        return CheckResult::Correct;
                    }
                    return CheckResult::Incorrect;
                }
                let encryption_key = &derived[..key_len];
                let mac_key = &derived[key_len..2 * key_len];
                let computed_auth = crypto::hmac_sha1(mac_key, ciphertext);
                if computed_auth[..10] != auth[..] {
                    return CheckResult::Incorrect;
                }
                let cipher = match crypto::AesCipher::new(encryption_key) {
                    Some(cipher) => cipher,
                    None => return CheckResult::Incorrect,
                };
                let mut compressed = Vec::with_capacity(ciphertext.len());
                let mut counter: u128 = 1;
                for chunk in ciphertext.chunks(16) {
                    let keystream = cipher.encrypt_block(&counter.to_le_bytes());
                    for (i, &byte) in chunk.iter().enumerate() {
                        compressed.push(byte ^ keystream[i]);
                    }
                    counter += 1;
                }
                let plain = match crate::decompress::decompress(self.method, &compressed, self.uncompressed_size) {
                    Ok(plain) => plain,
                    Err(_) => return CheckResult::Incorrect,
                };
                if plain.len() as u64 != self.uncompressed_size {
                    return CheckResult::Incorrect;
                }
                if info.version == 1 && crypto::crc32(&plain) != self.crc32 {
                    return CheckResult::Incorrect;
                }
                CheckResult::Correct
            }
        }
    }
}
EOF
"}

