// ---------- Password checking data ----------

#[derive(Debug)]
pub enum UnexpectedError {
    UnsupportedArchive(&'static str),
    Io(std::io::Error),
}

pub enum CheckResult {
    Correct,
    Incorrect,
    Unexpected(UnexpectedError),
}

#[derive(Debug)]
enum ZipReadError {
    Io(std::io::Error),
}

pub struct PasswordChecker {
    method: u16,
    crc32: u32,
    uncompressed_size: u64,
    kind: CheckerKind,
}

enum CheckerKind {
    Traditional {
        check_byte: u8,
        encrypted: Vec<u8>,
    },
    Aes {
        info: AesInfo,
        salt: Vec<u8>,
        verifier: Vec<u8>,
        after_verifier: Vec<u8>,
    },
}

impl SelectedEntry {
    pub fn into_checker(self) -> PasswordChecker {
        let start = self.data_offset;
        let available = if start < self.archive_bytes.len() {
            let wanted = self.entry.compressed_size;
            let end = if wanted > (self.archive_bytes.len() - start) as u64 {
                self.archive_bytes.len()
            } else {
                start + wanted as usize
            };
            &self.archive_bytes[start..end]
        } else {
            &[]
        };
        let raw = available.to_vec();
        match &self.entry.aes_info {
            None => {
                let check_byte = if self.entry.flags & 0x0008 != 0 {
                    (self.entry.mod_time >> 8) as u8
                } else {
                    (self.entry.crc32 >> 24) as u8
                };
                PasswordChecker {
                    method: self.entry.method,
                    crc32: self.entry.crc32,
                    uncompressed_size: self.entry.uncompressed_size,
                    kind: CheckerKind::Traditional { check_byte, encrypted: raw },
                }
            }
            Some(info) => {
                let salt_len = info.salt_len();
                // Constructing the reader for an AES entry reads its
                // salt and password-verification value up front.  The
                // archive has been validated by this point, so a short
                // entry is not expected here.
                let header_len = salt_len + 2;
                if raw.len() < header_len {
                    let mut buffer = vec![0u8; header_len];
                    use std::io::Read;
                    let result: Result<(), ZipReadError> = (&raw[..])
                        .read_exact(&mut buffer)
                        .map_err(ZipReadError::Io);
                    let _validated: () = result.expect("Archive validated before-hand");
                    unreachable!()
                }
                PasswordChecker {
                    method: info.actual_method,
                    crc32: self.entry.crc32,
                    uncompressed_size: self.entry.uncompressed_size,
                    kind: CheckerKind::Aes {
                        info: info.clone(),
                        salt: raw[..salt_len].to_vec(),
                        verifier: raw[salt_len..salt_len + 2].to_vec(),
                        after_verifier: raw[salt_len + 2..].to_vec(),
                    },
                }
            }
        }
    }
}

impl PasswordChecker {
    pub fn is_supported_method(&self) -> bool {
        crate::decompress::is_supported_method(self.method)
    }

    pub fn check(&self, password: &str) -> CheckResult {
        match &self.kind {
            CheckerKind::Traditional { check_byte, encrypted } => {
                if !self.is_supported_method() {
                    return CheckResult::Unexpected(UnexpectedError::UnsupportedArchive(
                        "Compression method not supported",
                    ));
                }
                if encrypted.len() < 12 {
                    use std::io::Read;
