                    return CheckResult::Incorrect;
                }
                if crypto::crc32(&plain) != self.crc32 {
                    return CheckResult::Incorrect;
                }
                CheckResult::Correct
            }
            CheckerKind::Aes { info, salt, verifier, after_verifier } => {
                let key_len = info.key_len();
