                };
                if plain.len() as u64 != self.uncompressed_size {
                    return CheckResult::Incorrect;
                }
                if info.version == 1 && crypto::crc32(&plain) != self.crc32 {
                    return CheckResult::Incorrect;
                }
                CheckResult::Correct
            }
        }
    }
}
