        let content = std::fs::read_to_string(path)?;
        return Ok(content.chars().collect());
    }
    let mut charset = BTreeSet::new();
    for option in options.charset.chars() {
        let characters = match option {
            'l' => CHARSET_LOWER,
            'u' => CHARSET_UPPER,
            'd' => CHARSET_DIGITS,
