    if duration.is_zero() {
        return "0s".to_string();
    }
    let mut pieces: Vec<String> = Vec::new();
    let mut seconds = duration.as_secs();

    let years = seconds / 31_557_600;
    if years > 0 {
        pieces.push(format!("{}y", years));
        seconds %= 31_557_600;
    }
    let months = seconds / 2_629_800;
    if months > 0 {
        pieces.push(format!("{}M", months));
        seconds %= 2_629_800;
    }
    let days = seconds / 86_400;
    if days > 0 {
        pieces.push(format!("{}d", days));
        seconds %= 86_400;
    }
    let hours = seconds / 3_600;
    if hours > 0 {
        pieces.push(format!("{}h", hours));
        seconds %= 3_600;
    }
    let minutes = seconds / 60;
    if minutes > 0 {
        pieces.push(format!("{}m", minutes));
        seconds %= 60;
    }
    if seconds > 0 {
        pieces.push(format!("{}s", seconds));
    }

    let nanos = duration.subsec_nanos();
    let millis = nanos / 1_000_000;
    let micros = (nanos % 1_000_000) / 1_000;
    let remaining_nanos = nanos % 1_000;
    if millis > 0 {
        pieces.push(format!("{}ms", millis));
    }
    if micros > 0 {
        pieces.push(format!("{}us", micros));
    }
    if remaining_nanos > 0 {
        pieces.push(format!("{}ns", remaining_nanos));
    }
    if pieces.is_empty() {
        "0s".to_string()
    } else {
        pieces.join(" ")
    }
}

fn run(options: &CliOptions) -> AppResult<Option<String>> {
    validate_cli(options)?;
    let workers = options.workers.unwrap_or(32);

    if let Some(dictionary_path) = &options.password_dictionary {
        let selected = load_selected_entry(&options.input_file, options.file_number)?;
        let checker = Arc::new(selected.into_checker());
        let passwords = password_worker::read_dictionary(dictionary_path)?;
        return Ok(password_worker::find_with_dictionary(checker, passwords, workers));
    }

    let charset = build_charset(options)?;
    validate_starting_password(options, &charset)?;
    let selected = load_selected_entry(&options.input_file, options.file_number)?;
    let checker = Arc::new(selected.into_checker());
    let generator = PasswordGenerator::new(
        &charset,
        options.min_password_len,
        options.max_password_len,
        options.starting_password.as_deref(),
    );
    Ok(password_worker::find_with_brute_force(checker, generator, workers))
}

fn main() {
    let options = parse_options();
    let start = Instant::now();
    match run(&options) {
        Ok(found) => {
            println!("Time elapsed: {}", format_duration(start.elapsed()));
            match found {
                Some(password) => println!("Password found:{}", password),
                None => println!("Password not found"),
            }
        }
        Err(error) => {
            eprintln!("{}", error);
            std::process::exit(1);
        }
    }
}
