anchor="""pub fn hmac_sha1(key: &[u8], message: &[u8]) -> [u8; 20] {"""
newfn="""pub fn pbkdf2_block(password: &[u8], salt: &[u8], iterations: u32, block_index: u32) -> [u8; 20] {
    let hmac = HmacSha1::new(password);
    let mut first_message = Vec::with_capacity(salt.len() + 4);
    first_message.extend_from_slice(salt);
    first_message.extend_from_slice(&block_index.to_be_bytes());
    let mut u = hmac.compute(&first_message);
    let mut result = u;
    let mut i = 1;
    while i < iterations {
        u = hmac.compute(&u);
        for j in 0..20 {
            result[j] ^= u[j];
        }
        i += 1;
    }
    result
}

"""
