                let mut derived = vec![0u8; 2 * key_len + 2];
                crypto::pbkdf2_hmac_sha1(password.as_bytes(), salt, 1000, &mut derived);
                if &derived[2 * key_len..] != verifier.as_slice() {
                    return CheckResult::Incorrect;
                }"""
new="""                let key_len = info.key_len();
                // The two verification bytes live in a single PBKDF2
                // block; deriving that block first rejects nearly
                // every candidate without deriving the complete key.
                let verifier_offset = 2 * key_len;
                let verifier_block_index = (verifier_offset / 20) as u32 + 1;
                let verifier_block = crypto::pbkdf2_block(
                    password.as_bytes(),
                    salt,
                    1000,
                    verifier_block_index,
