                let verifier_in_block = verifier_offset % 20;
                if verifier_block[verifier_in_block..verifier_in_block + 2] != verifier[..] {
                    return CheckResult::Incorrect;
                }
                let mut derived = vec![0u8; 2 * key_len + 2];
