    if eocd_pos + 22 > bytes.len() {
        return Err(invalid_zip("invalid Zip archive: Could not find EOCD"));
    }
    let disk_number = u16_at(bytes, eocd_pos + 4);
    let central_disk = u16_at(bytes, eocd_pos + 6);
    if disk_number != 0 || central_disk != 0 {
        return Err(invalid_zip(
            "unsupported Zip archive: Support for multi-disk files is not implemented",
        ));
    }
    let mut disk_entries = u16_at(bytes, eocd_pos + 8) as u64;
    let mut total = u16_at(bytes, eocd_pos + 10) as u64;
    let mut size = u32_at(bytes, eocd_pos + 12) as u64;
    let mut offset = u32_at(bytes, eocd_pos + 16) as u64;

    // ZIP64 end of central directory, when any ordinary field is set to
    // its sentinel value.
    if disk_entries == 0xffff
        || total == 0xffff
        || size == 0xffffffff
        || offset == 0xffffffff
        || disk_number == 0xffff
        || central_disk == 0xffff
