                    if disk_entries == 0xffff {
                        disk_entries = u64_at(bytes, zip64_pos + 24);
                    }
                    if total == 0xffff {
                        total = u64_at(bytes, zip64_pos + 32);
                    }
                    if size == 0xffffffff {
                        size = u64_at(bytes, zip64_pos + 40);
                    }
                    if offset == 0xffffffff {
                        offset = u64_at(bytes, zip64_pos + 48);
                    }
                }
            }
        }
    }
    Ok(EocdInfo { disk_entries, total_entries: total, central_size: size, central_offset: offset })
}

